require dirname(__DIR__,2).'/app/bootstrap.php';if(empty($_SESSION['admin'])||time()-(int)($_SESSION['last_seen']??0)>1800){http_response_code(403);exit('Inicia sesión en administración.');}$_SESSION['last_seen']=time();require dirname(__DIR__,2).'/app/PublicRequestService.php';$error='';
