?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solicitudes de usuarios | Administración</title><link rel="stylesheet" href="../assets/admin.css"><link rel="stylesheet" href="../assets/account-registration.css"><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page"><?php require __DIR__.'/_navigation.php';?><h1>Solicitudes de usuarios</h1><p>Sugerencias, peticiones, quejas y reclamos. Guardar una nota no envía un correo: responde mediante el canal del equipo y registra aquí la atención.</p><?php if($error):?><p role="alert"><?=esc($error)?></p><?php endif;?><?php if(!$requests):?><p>No hay solicitudes registradas.</p><?php endif;?><?php if($requests):?><div class="destination-admin-table"><table><thead><tr><th>Referencia / fecha</th><th>Tipo</th><th>Persona</th><th>Estado</th><th>Contenido y atención</th></tr></thead><tbody><?php foreach($requests as $row):?><tr><td><?=esc($row['reference'])?><br><small><?=esc($row['created_at'])?></small></td><td><?=esc(PublicRequestService::TYPES[$row['request_type']]??$row['request_type'])?></td><td><?=esc($row['name'])?><br><?=esc($row['email'])?></td><td><?=esc(['pending'=>'Pendiente','in_review'=>'En atención','resolved'=>'Atendida'][$row['status']]??$row['status'])?></td><td><details class="admin-row-detail"><summary>Ver y atender</summary><p><?=nl2br(esc($row['message']))?></p><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=esc($row['id'])?>"><label>Estado<select name="status"><?php foreach(['pending'=>'Pendiente','in_review'=>'En atención','resolved'=>'Atendida'] as $status=>$label):?><option value="<?=esc($status)?>" <?=$row['status']===$status?'selected':''?>><?=esc($label)?></option><?php endforeach;?></select></label><label>Nota interna de atención<textarea name="response_note" maxlength="10000"><?=esc($row['response_note'])?></textarea></label><button class="pill">Guardar revisión</button></form></details></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></body></html>
